#include <bits/stdc++.h>
using namespace std;

const int MAXN = 25;
const int INF = 10007;
const int MAXT = 65;
const int MAXC = 12;

int n, k;
string T1[MAXN], T2[MAXN];
int distZ[MAXN][MAXN];
int memo[MAXT][MAXC][MAXC][MAXC][MAXC];
int dirX[4] = {1, 0, -1, 0};
int dirY[4] = {0, 1, 0, -1};
vector<pair<int,int>> sources, sinks;

struct RelabelFlow {
    struct Edge {
        int from, to, cap, flow;
        Edge(int from, int to, int cap, int flow = 0) : from(from), to(to), cap(cap), flow(flow) {}
    };
    int N;
    vector<Edge> edges;
    vector<vector<int>> adj;
    vector<int> h, inQ, cnt;
    vector<int> ex;
    queue<int> q;

    RelabelFlow(int N) : N(N), cnt(N << 1), adj(N), h(N), inQ(N), ex(N) {}

    int addEdge(int u, int v, int cap) {
        adj[u].push_back((int)edges.size());
        edges.emplace_back(u, v, cap);
        adj[v].push_back((int)edges.size());
        edges.emplace_back(v, u, 0);
        return adj[u].back();
    }

    void enQueue(int u) {
        if (!inQ[u] && ex[u] > 0) {
            q.push(u);
            inQ[u] = true;
        }
    }

    void pushEdge(int id) {
        Edge &e = edges[id];
        int d = min(e.cap - e.flow, ex[e.from]);
        if (d > 0 && h[e.from] > h[e.to]) {
            e.flow += d;
            ex[e.to] += d;
            ex[e.from] -= d;
            edges[id ^ 1].flow -= d;
            enQueue(e.to);
        }
    }

    void relabelNode(int u) {
        cnt[h[u]]--;
        h[u] = 2 * N - 2;
        for (int i = 0; i < (int)adj[u].size(); ++i) {
            Edge &e = edges[adj[u][i]];
            if (e.cap > e.flow) h[u] = min(h[u], h[e.to]);
        }
        cnt[++h[u]]++;
    }

    void gap(int height) {
        for (int u = 0; u < N; ++u) {
            if (h[u] >= height && h[u] < N) {
                cnt[h[u]]--;
                h[u] = N;
                cnt[N]++;
                enQueue(u);
            }
        }
    }

    void discharge(int u) {
        for (int i = 0; ex[u] > 0 && i < (int)adj[u].size(); ++i) {
            pushEdge(adj[u][i]);
        }
        if (ex[u] > 0) {
            if (h[u] < N && cnt[h[u]] < 2) gap(h[u]);
            else relabelNode(u);
        } else if (!q.empty()) {
            q.pop();
            inQ[u] = false;
        }
    }

    int maxflow(int s, int t) {
        h[s] = N;
        inQ[s] = inQ[t] = true;
        cnt[0] = N - (cnt[N] = 1);
        for (int i = 0; i < (int)adj[s].size(); ++i) {
            ex[s] += edges[adj[s][i]].cap;
            pushEdge(adj[s][i]);
        }
        while (!q.empty()) discharge(q.front());
        return ex[t];
    }
};

void computeDist(int sx, int sy) {
    memset(distZ, -1, sizeof distZ);
    queue<pair<int,int>> q;
    distZ[sx][sy] = 0;
    q.push({sx, sy});
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirX[d];
            int ny = y + dirY[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (distZ[nx][ny] != -1) continue;
            if (T2[nx][ny] == 'Y' || T2[nx][ny] == 'Z') continue;
            distZ[nx][ny] = distZ[x][y] + 1;
            q.push({nx, ny});
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    memset(memo, -1, sizeof memo);
    cin >> n >> k;
    for (int i = 0; i < n; ++i) cin >> T1[i];
    for (int i = 0; i < n; ++i) cin >> T2[i];

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (T2[i][j] == 'Z') zx = i, zy = j;

    computeDist(zx, zy);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distZ[i][j] == -1) distZ[i][j] = INF;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = T1[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') sources.push_back({i, j});
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            char c = T2[i][j];
            if (c != 'Z' && c != 'Y' && c != '0') sinks.push_back({i, j});
        }

    function<int(int,int,int,int,int)> can = [&](int t, int x0, int y0, int x, int y) -> int {
        if (distZ[x0][y0] < t) return 0;
        if (x0 == x && y0 == y) return 1;
        if (t >= k) return 0;
        if (distZ[x0][y0] <= t) return 0;
        int &res = memo[t][x0][y0][x][y];
        if (res != -1) return res;
        for (int d = 0; d < 4; ++d) {
            int nx = x0 + dirX[d];
            int ny = y0 + dirY[d];
            if (nx < 0 || nx >= n || ny < 0 || ny >= n) continue;
            if (T1[nx][ny] == 'Y' || T1[nx][ny] == 'Z') continue;
            if (can(t + 1, nx, ny, x, y)) return res = 1;
        }
        return res = 0;
    };

    int S = 0;
    int T = (int)sources.size() + (int)sinks.size() + 1;
    RelabelFlow rf(T + 1);

    for (int i = 0; i < (int)sources.size(); ++i)
        rf.addEdge(S, i + 1, T1[sources[i].first][sources[i].second] - '0');

    for (int i = 0; i < (int)sinks.size(); ++i)
        rf.addEdge((int)sources.size() + i + 1, T,
                   T2[sinks[i].first][sinks[i].second] - '0');

    for (int i = 0; i < (int)sources.size(); ++i)
        for (int j = 0; j < (int)sinks.size(); ++j)
            if (can(0, sources[i].first, sources[i].second,
                    sinks[j].first, sinks[j].second))
                rf.addEdge(i + 1, (int)sources.size() + j + 1, INF);

    cout << rf.maxflow(S, T) << '\n';
    return 0;
}
